def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = []
    own = []
    for h in history:
        own.append(h[0])
        opp.append(h[1])

    opp_def_total = 0
    own_def_total = 0
    for x in opp:
        if x == 'D':
            opp_def_total += 1
    for x in own:
        if x == 'D':
            own_def_total += 1

    # Score tracking
    my_score = 0
    opp_score = 0
    cc = 0
    cd = 0
    dc = 0
    dd = 0
    for i in range(n):
        a = own[i]
        b = opp[i]
        if a == 'C' and b == 'C':
            my_score += 3
            opp_score += 3
            cc += 1
        elif a == 'C' and b == 'D':
            opp_score += 5
            cd += 1
        elif a == 'D' and b == 'C':
            my_score += 5
            dc += 1
        else:
            my_score += 1
            opp_score += 1
            dd += 1

    # Perfect cooperator: nurture mutual cooperation, late-game exploit lightly.
    if opp_def_total == 0:
        if n >= 95 and rng.random() < 0.35:
            return 'D'
        return 'C'

    # Perfect defector or near-perfect: defect.
    if dc + cc == 0:
        return 'D'

    last_own = own[-1]
    last_opp = opp[-1]

    # Recent window analysis
    if n >= 12:
        window = 12
    else:
        window = n
    recent_def = 0
    recent_my_def = 0
    for i in range(n - window, n):
        if opp[i] == 'D':
            recent_def += 1
        if own[i] == 'D':
            recent_my_def += 1

    opp_coop_rate = (n - opp_def_total) / n

    # Opponent defected last round
    if last_opp == 'D':
        # If opponent is mostly cooperative, occasionally forgive to avoid mutual destruction
        if opp_coop_rate > 0.75 and rng.random() < 0.20:
            return 'C'
        # If opponent has defected very recently and often, punish hard
        if recent_def >= 4:
            return 'D'
        # If we're being heavily exploited and far behind, defect
        if opp_score > my_score + 25:
            return 'D'
        # Otherwise defect once as retaliation
        return 'D'

    # Opponent cooperated last round
    # If we just defected, try to repair by cooperating
    if last_own == 'D':
        # If opponent's cooperation is solid, return to cooperation
        if opp_coop_rate > 0.6:
            return 'C'
        # If opponent has been mostly defecting, keep defecting
        if opp_coop_rate < 0.4:
            return 'D'
        # Otherwise cooperate to test
        if rng.random() < 0.7:
            return 'C'
        return 'D'

    # Both cooperated last round
    # If opponent has been generally cooperative, continue cooperating
    if opp_coop_rate >= 0.8:
        # Slight probing in late rounds
        if n >= 90 and rng.random() < 0.15:
            return 'D'
        return 'C'

    # Moderate cooperator: cooperate but watch for exploitation
    if opp_coop_rate >= 0.5:
        if recent_def >= 3:
            return 'D'
        return 'C'

    # Mostly defecting opponent: defect
    if opp_coop_rate < 0.4:
        # Occasionally cooperate to test for reformation
        if n >= 4 and rng.random() < 0.1:
            return 'C'
        return 'D'

    # Middle ground: tit-for-tat leaning cooperative
    if recent_def >= 2:
        return 'D'
    return 'C'
